        diff2 = "diff --git a/cmd/main.go b/cmd/main.go\n+++ b/cmd/main.go\n@@ -1 +1 @@\n+dsn := \"postgres://app:Xk9v2mQpL7sT4wRz9@db.prod.example.com/x\"\n"
