describe('parseExtensionEntry', () => {
	it('괄호가 없으면 확장자 하나로 처리한다', () => {
		expect(parseExtensionEntry('PDF')).toEqual(['.pdf'])
	})

	it('괄호 안의 확장자를 모두 분리하며 점을 중복해서 붙이지 않는다', () => {
		expect(parseExtensionEntry('엑셀(xlsx,xls)')).toEqual(['.xlsx', '.xls'])
	})

	it('구분자 주변 공백과 이미 붙은 점을 정리한다', () => {
		expect(parseExtensionEntry('이미지( .jpg , JPEG , png )')).toEqual(['.jpg', '.jpeg', '.png'])
	})

	it('값이 비어 있으면 빈 배열을 반환한다', () => {
		expect(parseExtensionEntry('')).toEqual([])
		expect(parseExtensionEntry(null)).toEqual([])
		expect(parseExtensionEntry('   ')).toEqual([])
	})

	it('ocr 모드에서는 처리 불가 확장자를 제외한다', () => {
		expect(parseExtensionEntry('txt', 'ocr')).toEqual([])
		expect(parseExtensionEntry('문서(pdf,txt,md)', 'ocr')).toEqual(['.pdf'])
	})

	it('호출부가 대문자 OCR 을 넘겨도 동일하게 제외한다', () => {
		expect(parseExtensionEntry('문서(pdf,txt,md)', 'OCR')).toEqual(['.pdf'])
	})

	it('ocr 이 아닌 모드에서는 제외하지 않는다', () => {
		expect(parseExtensionEntry('문서(pdf,txt)', 'simple')).toEqual(['.pdf', '.txt'])
	})
})

